cd /tmp/binlog_parser && cat > Program.cs << 'EOF'
using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;
using System.Collections.Generic;

var build = BinaryLog.ReadBuild(args[0]);
var errors = build.FindChildrenRecursive<Error>();
var warnings = build.FindChildrenRecursive<Warning>();

Console.WriteLine("=== BUILD ERRORS ===\n");
var grouped = new Dictionary<string, List<Error>>();
foreach (var error in errors)
{
    var project = error.GetNearestParent<Project>();
    var projectName = project?.Name ?? "unknown";
    if (!grouped.ContainsKey(projectName))
        grouped[projectName] = new List<Error>();
    grouped[projectName].Add(error);
}

foreach (var kvp in grouped.OrderBy(k => k.Key))
{
    Console.WriteLine($"--- Project: {kvp.Key} ---");
    foreach (var error in kvp.Value)
    {
        Console.WriteLine($"  {error.Code}: {error.Text}");
        if (!string.IsNullOrEmpty(error.File))
            Console.WriteLine($"    File: {error.File}({error.LineNumber},{error.ColumnNumber})");
    }
    Console.WriteLine();
}

Console.WriteLine($"Total errors: {errors.Count()}");
Console.WriteLine($"Total projects with errors: {grouped.Count}");

// Check for projects that failed due to dependency failures
Console.WriteLine("\n=== PROJECTS WITH BUILD FAILURES (including dependency failures) ===\n");
var projects = build.FindChildrenRecursive<Project>();
foreach (var proj in projects)
{
    var buildMessages = proj.FindChildrenRecursive<Message>()
        .Where(m => m.Text != null && (m.Text.Contains("previously failed") || m.Text.Contains("depends on")));
    foreach (var msg in buildMessages.Take(5))
    {
        if (msg.Text.Contains("previously failed") || msg.Text.Contains("not build"))
            Console.WriteLine($"  [{proj.Name}] {msg.Text}");
    }
}

// Also check for MSB errors
Console.WriteLine("\n=== MSB-LEVEL ERRORS/WARNINGS ===\n");
foreach (var w in warnings.Where(w => w.Code != null && (w.Code.StartsWith("MSB") || w.Code.StartsWith("NU"))))
{
    var project = w.GetNearestParent<Project>();
    Console.WriteLine($"  [{project?.Name}] {w.Code}: {w.Text}");
}
EOF

